package server

func init() {
	pages["sna_circuits"] = `{{define "content"}}
<div class="d-flex justify-content-between align-items-center mb-3"><div><h1>{{if .All}}All SNA circuits{{else}}SNA circuits{{end}}</h1><p class="text-muted">A circuit is a transport path between two routers and may carry one or more IBM SNA sessions.</p></div><a class="btn btn-outline-primary" href="{{if .All}}/admin/circuits{{else}}/circuits{{end}}">Refresh</a></div>
<section class="card shadow-sm mb-4"><div class="card-body"><h2 class="h4">Active circuits <span class="badge text-bg-primary">{{len .Active}}</span></h2><div class="table-responsive"><table class="table table-sm table-striped align-middle"><thead><tr><th>Circuit</th><th>Path</th><th>State / profile</th><th>Activity</th><th>Transport credit</th><th>Statistics</th><th></th></tr></thead><tbody>{{range .Active}}<tr><td><code>{{.ID}}</code><br><small>opened {{date .OpenedAt}}</small></td><td>{{.SourceRouterName}} → {{.TargetRouterName}}</td><td>{{.State}}<br><small>{{.Profile}}</small></td><td>{{date .LastActivityAt}}</td><td><small>Source: {{.SourceBytes}} / {{.SourceAllowance}} bytes<br>Target: {{.TargetBytes}} / {{.TargetAllowance}} bytes</small></td><td><small>Events: {{.SourceEvents}} / {{.TargetEvents}}<br>Peak queue: {{.PeakQueuedBytes}} bytes</small></td><td><form method="post" action="{{if $.All}}/admin/circuits/{{.ID}}/reset{{else}}/circuits/{{.ID}}/reset{{end}}" onsubmit="return confirm('Reset this SNA circuit?')"><input type="hidden" name="csrf" value="{{$.CSRF}}"><button class="btn btn-outline-danger btn-sm">Reset circuit</button></form></td></tr>{{else}}<tr><td colspan="7">No active SNA circuits.</td></tr>{{end}}</tbody></table></div></div></section>
<section class="card shadow-sm"><div class="card-body"><h2 class="h4">Circuit history</h2><p class="text-muted">Completed summaries are retained for 90 days. Navigation uses stable cursor paging while new records arrive.</p>
<form method="get" class="row g-2 align-items-end mb-3"><div class="col-lg-4"><label class="form-label" for="history-q">Search</label><input class="form-control" id="history-q" name="q" value="{{.History.Search}}" placeholder="Circuit, router, owner, actor or reason"></div><div class="col-sm-3 col-lg-2"><label class="form-label" for="history-state">Result</label><select class="form-select" id="history-state" name="state"><option value="">All</option><option value="closed" {{if eq .History.State "closed"}}selected{{end}}>Closed</option><option value="reset" {{if eq .History.State "reset"}}selected{{end}}>Reset</option></select></div><div class="col-sm-4 col-lg-2"><label class="form-label" for="history-reason">Reason</label><input class="form-control" id="history-reason" name="reason" value="{{.History.Reason}}"></div><div class="col-sm-3 col-lg-2"><label class="form-label" for="history-from">Closed from</label><input class="form-control" id="history-from" type="date" name="from" value="{{.History.From}}"></div><div class="col-sm-3 col-lg-2"><label class="form-label" for="history-to">Closed through</label><input class="form-control" id="history-to" type="date" name="to" value="{{.History.To}}"></div><div class="col-sm-3 col-lg-2"><label class="form-label" for="history-size">Rows</label><select class="form-select" id="history-size" name="page_size"><option {{if eq .History.PageSize 25}}selected{{end}}>25</option><option {{if eq .History.PageSize 50}}selected{{end}}>50</option><option {{if eq .History.PageSize 100}}selected{{end}}>100</option><option {{if eq .History.PageSize 200}}selected{{end}}>200</option></select></div><div class="col-auto"><button class="btn btn-primary">Apply</button> <a class="btn btn-link" href="{{if .All}}/admin/circuits{{else}}/circuits{{end}}">Clear</a></div></form>
{{if .History.Pending}}<div class="alert alert-warning"><strong>{{len .History.Pending}} history write(s) pending or failed.</strong><div class="table-responsive"><table class="table table-sm mb-0"><thead><tr><th>Circuit</th><th>Path</th><th>Closed</th><th>Result</th><th>Persistence</th></tr></thead><tbody>{{range .History.Pending}}<tr><td><code>{{.ID}}</code></td><td>{{.SourceRouterName}} → {{.TargetRouterName}}</td><td>{{date .ClosedAt}}</td><td>{{.State}} · {{.CloseReason}}</td><td>{{.Persistence}}</td></tr>{{end}}</tbody></table></div></div>{{end}}
<div class="d-flex justify-content-between mb-2"><span>Showing {{len .History.Items}} persisted result(s)</span><div>{{if .History.PrevURL}}<a class="btn btn-outline-secondary btn-sm" href="{{.History.PrevURL}}">Previous</a>{{end}} {{if .History.NextURL}}<a class="btn btn-outline-secondary btn-sm" href="{{.History.NextURL}}">Next</a>{{end}}</div></div><div class="table-responsive"><table class="table table-sm table-striped align-middle"><thead><tr><th>Circuit</th><th>Path</th><th>Profile</th><th>Timing</th><th>Result</th><th>Statistics</th></tr></thead><tbody>{{range .History.Items}}<tr><td><code>{{.ID}}</code></td><td>{{.SourceRouterName}}<br><small><code>{{.SourceRouterID}}</code></small><br>→ {{.TargetRouterName}}<br><small><code>{{.TargetRouterID}}</code></small></td><td>{{.Profile}}</td><td><small>Opened {{date .OpenedAt}}<br>{{if .ActivatedAt}}Activated {{date .ActivatedAt}}<br>{{end}}Closed {{date .ClosedAt}}</small></td><td>{{.State}}<br><small>{{.CloseReason}}{{if .ActorID}}<br>{{.ActorType}}: {{.ActorID}}{{end}}</small></td><td><small>Bytes: {{.SourceBytes}} / {{.TargetBytes}}<br>Events: {{.SourceEvents}} / {{.TargetEvents}}<br>Peak queue: {{.PeakQueuedBytes}} bytes</small></td></tr>{{else}}<tr><td colspan="6">No completed SNA circuits match these filters.</td></tr>{{end}}</tbody></table></div></div></section>
{{end}}`
}
